//! Actual same-A signatures exercise the first-report verifier. This local
//! mechanism test supplies trusted fixture policy before encoding the report;
//! it does not claim three-UID Root admission or execution of E/D/T.
use super::*;
use super::super::original_material::{ProviderAdmission, UnstartedProvider};
use super::super::super::evaluation_provider::fresh_training::PreparedBPanel;
use anyhow::Context as _;
use base64::Engine as _;
use base64::engine::general_purpose::STANDARD_NO_PAD;

fn held_fixture_policy(
    fixture: &UnstartedProvider,
    protocol: crate::OriginalCellEvaluationPanelRegistrationV1,
    trust: LearningEvidenceTrustV1,
) -> PreheldMaterialInputs {
    let source = &fixture.source_a;
    let [experience, dataset, generator, evaluator] = fixture.credentials.resident_checkpoint_signers();
    PreheldMaterialInputs {
        // These are trusted local fixture inputs, never parsed out of Report.
        // The cross-UID orchestrator must supply its own pre-held equivalents.
        task: PreheldTask {
            operation_id: id("positive-original-learning-operation"),
            principal_id: id(&source.scope.principal_digest.to_string()),
            agent_id: source.scope.agent_id.clone(), cell_id: source.scope.cell_id.clone(),
            source_run_id: source.scope.run_id.clone(), selected_artifact_digest: fixture.bundle.components.base,
            selected_bundle: fixture.bundle.clone(), envelope: fixture.material.initial.request.envelope.clone(),
            budget: LearningIterationBudgetV1 {
                maximum_dataset_rows: 1, maximum_dataset_bytes: 128, maximum_training_steps: 2,
                maximum_training_milliseconds: 10_000, maximum_artifact_bytes: 4_096,
            },
        },
        owners: LearningIterationOwnersV1 {
            evidence_trust_digest: fixture.material.verifier.trust_digest(),
            experience: experience.principal.principal_id.clone(), dataset: dataset.principal.principal_id.clone(),
            trainer: generator.principal.principal_id.clone(), evaluator: evaluator.principal.principal_id.clone(),
            proposal: id("positive-original-model"), selector: fixture.credentials.selector.principal.principal_id.clone(),
            next_use_observer: fixture.credentials.observer.principal.principal_id.clone(),
        },
        protocol, trust, generator, observer: fixture.credentials.observer.clone(), evaluator, experience, dataset,
        baseline: Arc::clone(&fixture.baseline), source_input: vec![Q, Q / 4],
        decision_snapshot: source.ndu_snapshot_digest, episode_id: id("positive-original-episode"),
        rule: crate::CellQ24DatasetRuleV1 { head: crate::CellQ24PrivateHeadV1::Prediction { index: 0 },
            unit_profile_digest: d("explicit-positive-terminal-unit") },
        optimizer: crate::CellQ24SgdRuleV1 { epochs: 2, learning_rate_q24: Q / 2 },
        update_scope: LearningUpdateScopeV2::Cell, freeze_snapshot_id: id("positive-original-dataset"),
        maximum_signature_lifetime_seconds: 600,
    }
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn first_pending_material_uses_full_original_signatures_and_preheld_policy() -> anyhow::Result<()> {
    let admission = ProviderAdmission::new().await?;
    let (_, _, trust) = material::original_fixture_trust_at(admission.objective, admission.trust_time)?;
    let panel = PreparedBPanel::new(admission.objective, admission.trust_time)?;
    let protocol = panel.registration().clone();
    let fixture = Box::pin(UnstartedProvider::new(admission, protocol.evaluation_profile())).await?;
    let result: anyhow::Result<()> = (|| {
        let before = fixture.original_bytes()?;
        let held = held_fixture_policy(&fixture, protocol, trust);
        let ledger = fixture.ledger.lock().map_err(|_| anyhow::anyhow!("original Ledger poisoned"))?.snapshot()?;
        let raw = encode_original_report(&fixture.material, &ledger, &fixture.original_decision, &fixture.original_outcome)?;
        let pending = RootMaterialContract::from_preheld(held.clone())?.verify_report(&raw)?;
        assert_eq!(pending.admission_binding()?, crate::RootResidentLearningProfileV3::admission_binding(
            &fixture.material.initial, &fixture.material.scope, &fixture.material.verifier)?);
        assert_eq!(pending.material.initial, fixture.material.initial);
        assert_eq!(pending.material.scope, fixture.material.scope);
        assert_eq!(pending.material.freeze_evidence, fixture.material.freeze_evidence);
        anyhow::ensure!(pending.material.initial.receipts.is_empty(), "Pending contains no completed E, D or T claim");
        drop(pending);
        let base: serde_json::Value = serde_json::from_slice(&raw)?;
        for role in ["decision", "outcome", "freeze"] {
            for field in ["principal_id", "trust", "scope", "objective", "payload_digest"] {
                let mut changed = base.clone(); changed[role][field] = serde_json::json!(d("foreign-original-context").to_string());
                anyhow::ensure!(RootMaterialContract::from_preheld(held.clone())?
                    .verify_report(&wire::canonical_mutation(changed)?).is_err(), "{role} {field}");
            }
            let mut changed = base.clone();
            let mut signature = STANDARD_NO_PAD.decode(changed[role]["signature"].as_str().context("signature")?)?;
            signature[0] ^= 1; changed[role]["signature"] = serde_json::json!(STANDARD_NO_PAD.encode(signature));
            anyhow::ensure!(RootMaterialContract::from_preheld(held.clone())?
                .verify_report(&wire::canonical_mutation(changed)?).is_err(), "full-length original {role} signature");
        }
        let mut changed = base.clone(); changed["completeness"]["omitted_count_bound"] = serde_json::json!(1);
        anyhow::ensure!(RootMaterialContract::from_preheld(held.clone())?
            .verify_report(&wire::canonical_mutation(changed)?).is_err(), "the full signed completeness, not its digest alone");
        let mut wrong = held.clone(); wrong.observer.controller_id = wrong.generator.controller_id.clone();
        anyhow::ensure!(RootMaterialContract::from_preheld(wrong).is_err(), "full pre-held signer binding includes controller");
        let mut wrong = held.clone(); wrong.task.budget.maximum_training_steps += 1;
        anyhow::ensure!(RootMaterialContract::from_preheld(wrong)?.verify_report(&raw).is_err(), "whole frozen cost contract");
        let mut wrong = held.clone(); wrong.source_input[0] += 1;
        anyhow::ensure!(RootMaterialContract::from_preheld(wrong)?.verify_report(&raw).is_err(), "same original batch and update rule");
        let mut wrong = held.clone(); wrong.task.envelope.expiry_unix_seconds = now()?;
        anyhow::ensure!(RootMaterialContract::from_preheld(wrong).is_err(), "expired original contract cannot be renewed by report");
        let mut changed_initial = fixture.material.initial.clone();
        changed_initial.request.completed_task_receipt = d("unverified-source-substitution");
        let changed_initial = LearningIterationCoordinatorV1::new(changed_initial.request, changed_initial.owners)?;
        let mut changed = base.clone(); changed["initial"] = serde_json::json!(STANDARD_NO_PAD.encode(
            encode_original_owner_snapshot_v1(changed_initial.snapshot())?));
        anyhow::ensure!(RootMaterialContract::from_preheld(held.clone())?
            .verify_report(&wire::canonical_mutation(changed)?).is_err(), "original freeze pins this exact Pending completion claim");
        let mut replay = LearningLedger::new();
        for record in ledger.records() {
            let mut event = record.event.clone();
            if let LedgerEvent::AuthenticatedDecisionV2(decision) = &mut event {
                decision.support_digest = d("different-Source-publication");
            }
            replay.append(event)?;
        }
        let mut changed = base.clone(); changed["ledger"] = serde_json::json!(STANDARD_NO_PAD.encode(
            encode_original_ledger_snapshot_v1(&replay.snapshot())?));
        anyhow::ensure!(RootMaterialContract::from_preheld(held.clone())?
            .verify_report(&wire::canonical_mutation(changed)?).is_err(), "canonical causal replay is not original signature authentication");
        let mut added = base.clone(); added["host_trust"] = serde_json::json!("child-selected");
        anyhow::ensure!(RootMaterialContract::from_preheld(held.clone())?.verify_report(&serde_json::to_vec(&added)?).is_err());
        let mut trailing = raw.clone(); trailing.push(b' ');
        anyhow::ensure!(RootMaterialContract::from_preheld(held.clone())?.verify_report(&trailing).is_err());
        anyhow::ensure!(RootMaterialContract::from_preheld(held)?.verify_report(&vec![0; wire::CONTROL_LIMIT + 1]).is_err());
        anyhow::ensure!(fixture.original_bytes()? == before, "verification did not write Source, ledger or any receipt owner");
        Ok(())
    })();
    drop(panel);
    let cleanup = fixture.finish().await;
    match (result, cleanup) {
        (Ok(()), Ok(_)) => Ok(()),
        (Err(error), cleanup) => Err(error.context(format!("original fixture cleanup: {cleanup:?}"))),
        (Ok(()), Err(error)) => Err(error),
    }
}

//! Bounded test control data. None of these decoded values is an owner or
//! authenticated Source publication; the parent supplies all trust and policy.
use super::*;
use base64::Engine as _;
use base64::engine::general_purpose::STANDARD_NO_PAD;
use serde::{Deserialize, Serialize};

const PURPOSE: &str = "hepta.fixture.pending-original-material.v1";
pub(super) const CONTROL_LIMIT: usize = 64 * 1024;
const SNAPSHOT_LIMIT: usize = 8192;

#[derive(Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct Evidence {
    evidence_id: String,
    principal_id: String,
    trust: String,
    scope: String,
    objective: String,
    authority_epoch: u64,
    issued_at: u64,
    expires_at: u64,
    payload_digest: String,
    signature: String,
}

impl Evidence {
    fn from_original(value: &SignedLearningEvidenceV1, role: LearningEvidenceRoleV1) -> anyhow::Result<Self> {
        anyhow::ensure!(value.role == role, "the field fixes the original evidence role");
        Ok(Self {
            evidence_id: value.evidence_id.to_string(), principal_id: value.principal_id.to_string(),
            trust: value.trust_digest.to_string(), scope: value.scope_digest.to_string(),
            objective: value.objective_digest.to_string(), authority_epoch: value.authority_epoch,
            issued_at: value.issued_at, expires_at: value.expires_at,
            payload_digest: value.payload_digest.to_string(), signature: STANDARD_NO_PAD.encode(value.signature),
        })
    }

    fn original(&self, role: LearningEvidenceRoleV1) -> anyhow::Result<SignedLearningEvidenceV1> {
        let signature = original_bytes(&self.signature, 64)?;
        let signature: [u8; 64] = signature.try_into().map_err(|_| anyhow::anyhow!("complete original signature"))?;
        Ok(SignedLearningEvidenceV1 {
            evidence_id: StableId::new(self.evidence_id.as_str())?,
            principal_id: StableId::new(self.principal_id.as_str())?, role,
            trust_digest: self.trust.parse()?, scope_digest: self.scope.parse()?,
            objective_digest: self.objective.parse()?, authority_epoch: self.authority_epoch,
            issued_at: self.issued_at, expires_at: self.expires_at,
            payload_digest: self.payload_digest.parse()?, signature,
        })
    }
}

#[derive(Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct Completeness {
    set_id: String,
    state_digest: String,
    generator_id: String,
    generator_code_digest: String,
    grammar_digest: String,
    hard_filter_digest: String,
    truncation_digest: String,
    candidates_digest: String,
    candidate_count: u32,
    omitted_count_bound: u32,
    canonical_order_digest: String,
    complete_for_generator: bool,
}

impl Completeness {
    fn from_original(value: &CandidateSetCompletenessReceiptV1) -> Self {
        Self {
            set_id: value.set_id.to_string(), state_digest: value.state_digest.to_string(),
            generator_id: value.generator_id.to_string(), generator_code_digest: value.generator_code_digest.to_string(),
            grammar_digest: value.grammar_digest.to_string(), hard_filter_digest: value.hard_filter_digest.to_string(),
            truncation_digest: value.truncation_digest.to_string(), candidates_digest: value.candidates_digest.to_string(),
            candidate_count: value.candidate_count, omitted_count_bound: value.omitted_count_bound,
            canonical_order_digest: value.canonical_order_digest.to_string(), complete_for_generator: value.complete_for_generator,
        }
    }

    fn original(&self) -> anyhow::Result<CandidateSetCompletenessReceiptV1> {
        Ok(CandidateSetCompletenessReceiptV1 {
            set_id: StableId::new(self.set_id.as_str())?, state_digest: self.state_digest.parse()?,
            generator_id: StableId::new(self.generator_id.as_str())?, generator_code_digest: self.generator_code_digest.parse()?,
            grammar_digest: self.grammar_digest.parse()?, hard_filter_digest: self.hard_filter_digest.parse()?,
            truncation_digest: self.truncation_digest.parse()?, candidates_digest: self.candidates_digest.parse()?,
            candidate_count: self.candidate_count, omitted_count_bound: self.omitted_count_bound,
            canonical_order_digest: self.canonical_order_digest.parse()?, complete_for_generator: self.complete_for_generator,
        })
    }
}

#[derive(Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct Report {
    purpose: String,
    initial: String,
    ledger: String,
    completeness: Completeness,
    decision: Evidence,
    decision_admitted_at: u64,
    outcome: Evidence,
    outcome_admitted_at: u64,
    freeze: Evidence,
    scope_binding: String,
}

pub(super) struct DecodedReport {
    pub(super) initial: LearningIterationSnapshotV1,
    pub(super) ledger: LedgerSnapshot,
    pub(super) completeness: CandidateSetCompletenessReceiptV1,
    pub(super) decision: SignedLearningEvidenceV1,
    pub(super) decision_admitted_at: u64,
    pub(super) outcome: SignedLearningEvidenceV1,
    pub(super) outcome_admitted_at: u64,
    pub(super) freeze: SignedLearningEvidenceV1,
    pub(super) scope_binding: Digest32,
}

fn original_bytes(value: &str, maximum: usize) -> anyhow::Result<Vec<u8>> {
    let bytes = STANDARD_NO_PAD.decode(value)?;
    anyhow::ensure!(!bytes.is_empty() && bytes.len() <= maximum
        && STANDARD_NO_PAD.encode(&bytes) == value, "complete canonical bounded bytes");
    Ok(bytes)
}

pub(super) fn encode_original_report(
    material: &Material,
    ledger: &LedgerSnapshot,
    decision: &material::OriginalDecisionEvidence,
    outcome: &material::OriginalOutcomeEvidence,
) -> anyhow::Result<Vec<u8>> {
    let snapshot = encode_original_owner_snapshot_v1(&material.initial)?;
    anyhow::ensure!(snapshot.len() <= SNAPSHOT_LIMIT, "original checkpoint codec limit");
    let records = ledger.records();
    anyhow::ensure!(records.len() == 2, "complete single-A fixture history, never a filtered subset");
    let report = Report {
        purpose: PURPOSE.into(), initial: STANDARD_NO_PAD.encode(snapshot),
        ledger: STANDARD_NO_PAD.encode(encode_original_ledger_snapshot_v1(ledger)?),
        completeness: Completeness::from_original(&decision.request.completeness),
        decision: Evidence::from_original(&decision.evidence, LearningEvidenceRoleV1::Generator)?,
        decision_admitted_at: decision.admitted_at,
        outcome: Evidence::from_original(&outcome.evidence, LearningEvidenceRoleV1::Observer)?,
        outcome_admitted_at: outcome.admitted_at,
        freeze: Evidence::from_original(&material.freeze_evidence, LearningEvidenceRoleV1::Evaluator)?,
        scope_binding: material.scope.binding().to_string(),
    };
    let bytes = serde_json::to_vec(&report)?;
    anyhow::ensure!(!bytes.is_empty() && bytes.len() <= CONTROL_LIMIT,
        "one complete control frame including JSON and base64 overhead");
    Ok(bytes)
}

pub(super) fn decode_report(bytes: &[u8]) -> anyhow::Result<DecodedReport> {
    anyhow::ensure!(!bytes.is_empty() && bytes.len() <= CONTROL_LIMIT, "bounded complete control frame");
    let report: Report = serde_json::from_slice(bytes)?;
    anyhow::ensure!(report.purpose == PURPOSE && serde_json::to_vec(&report)? == bytes,
        "fixed purpose, complete canonical report, no unknown fields or trailing bytes");
    let initial_bytes = original_bytes(&report.initial, SNAPSHOT_LIMIT)?;
    let initial = decode_original_owner_snapshot_v1(&initial_bytes)?;
    anyhow::ensure!(encode_original_owner_snapshot_v1(&initial)? == initial_bytes, "original full snapshot codec");
    let ledger_bytes = original_bytes(&report.ledger, MAX_ORIGINAL_LEDGER_SNAPSHOT_BYTES_V1)?;
    let ledger = decode_original_ledger_snapshot_v1(&ledger_bytes)?;
    anyhow::ensure!(encode_original_ledger_snapshot_v1(&ledger)? == ledger_bytes, "full original ledger replay and encoding");
    Ok(DecodedReport {
        initial, ledger, completeness: report.completeness.original()?,
        decision: report.decision.original(LearningEvidenceRoleV1::Generator)?,
        decision_admitted_at: report.decision_admitted_at,
        outcome: report.outcome.original(LearningEvidenceRoleV1::Observer)?,
        outcome_admitted_at: report.outcome_admitted_at,
        freeze: report.freeze.original(LearningEvidenceRoleV1::Evaluator)?,
        scope_binding: report.scope_binding.parse()?,
    })
}

pub(super) fn canonical_mutation(value: serde_json::Value) -> anyhow::Result<Vec<u8>> {
    Ok(serde_json::to_vec(&serde_json::from_value::<Report>(value)?)?)
}

